/* Curated source-backed templates: explicitly selected preparation paths, never invented full audits. */
function infoTemplateForm(){return `<details class="journey-advanced"><summary>Load a sourced UW Seattle Informatics checklist</summary><form id="info-template-form" class="form-grid"><label>Planning stage<select name="stage"><option value="current">Current UW Seattle student — admission preparation</option><option value="transfer">Transfer applicant — admission preparation</option><option value="core">Already admitted — supported core subset</option></select></label><label>Programming preparation<select name="programming"><option value="INFO 201">INFO 201 — also part of the core curriculum</option><option value="CSE 121">CSE 121 — introductory programming</option><option value="CSE 180">CSE 180 — source-listed admission alternative</option></select></label><label>Social sciences class (other than INFO 200)<select name="social">${['INFO 351','INFO 352','INFO 353','INFO 354','INFO 357','INFO 358'].map(code=>{const c=AcademicEvidence.info.courses.find(c=>c.code===code);return `<option value="${code}">${code} · ${esc(c.title)} · ${c.credits} credits</option>`}).join('')}</select></label><button class="btn">Load source-based checklist</button></form><p class="quiet-note">These are selected documented alternatives, not the only allowed courses. STAT 220 is the initial statistics choice. Course access and offerings require confirmation. Transfer credit from a community college is not inferred from the title; add a source-verified alternative to change its teaching school.</p><p class="quiet-note">The core subset excludes the unresolved INFO 290 / INFO 280 source conflict, university general education, residency and elective approvals. For core scheduling, this assumes you are already admitted. CSE 121 → 122 → 123 is a beginner preparation preference; the catalog describes placement/readiness rather than hard prerequisites for 122/123.</p><a class="journey-secondary" href="${AcademicEvidence.info.source}" target="_blank" rel="noopener">Official admission alternatives ↗</a></details>`}
function loadInfoTemplate(form){const f=Object.fromEntries(new FormData(form)),source=AcademicEvidence.info,byCode=new Map(source.courses.map(c=>[c.code,c])),entries=new Map(),institution='University of Washington Seattle';const add=(code,prereqs=[])=>{const record=byCode.get(code);if(!record)throw Error('Source record unavailable: '+code);const c={code,title:record.title,institution,credits:record.credits,units:'Quarter',source:record.source,prereqs:[],coreqs:[],completed:false,prerequisiteText:record.prerequisiteText||'',sourceWarning:record.warning||'',foundation:['INFO 200','INFO 201','STAT 220','CSE 121','CSE 122','CSE 123'].includes(code)};entries.set(code,{course:c,pre:prereqs});return c};const reqs=[],require=(code,phase,minGrade=null)=>{if(!entries.has(code))add(code);reqs.push({id:'info-'+code.replace(/ /g,'-')+'-'+phase,label:byCode.get(code).title,phase,count:1,choices:[MultiDegree.key(entries.get(code).course)],minGrade,source:phase==='admission'?source.source:source.curriculum.source,evidence:'Official source snapshot; selected preparation path'})};
 if(f.stage==='core'){for(const code of ['INFO 200','INFO 201','INFO 300','INFO 330','INFO 360','INFO 380']){add(code);require(code,'foundation',code==='INFO 201'?2:null)}add('CSE 121');add('CSE 122',['CSE 121']);add('CSE 123',['CSE 122']);entries.get('CSE 122').course.planningNote='Beginner preparation preference; placement may permit another entry point.';entries.get('CSE 123').course.planningNote='Beginner preparation preference; placement may permit another entry point.';require('CSE 123','foundation');add('INFO 340',['CSE 123','INFO 201']);entries.get('INFO 340').course.planningNote='Selected CSE 123 route; source permits the programming alternative concurrently, but this draft puts it earlier for preparation.';require('INFO 340','degree');add('INFO 442',['INFO 360','INFO 340']);require('INFO 442','degree');for(const code of ['INFO 351','INFO 352']){add(code);require(code,'degree')}add('INFO 490',['INFO 300','INFO 340','INFO 360']);entries.get('INFO 490').course.planningNote='Selected three-of-four prerequisite combination: INFO 300, 340 and 360; INFO 380 is another published alternative.';require('INFO 490','degree');add('INFO 491',['INFO 490']);require('INFO 491','degree');}
 else{if(f.stage==='current')require('INFO 200','admission',2);require(f.programming,'admission',2);require('STAT 220','admission',2);require(f.social,'admission',2)}
 for(const entry of entries.values())entry.course.prereqs=entry.pre.map(code=>MultiDegree.key(entries.get(code).course));const goalOld=(state.degreeGoals||[]).find(g=>/Informatics/i.test(g.name)&&/Seattle/.test(g.institution)&&g.requirements.length===0);if(!goalOld&&(state.degreeGoals||[]).length>=6)return toast('Use up to six goals.');if((state.degreeGoals||[]).some(g=>g.preset==='uw-info-'+f.stage))return toast('That Informatics template is already loaded.');const goal={id:goalOld?.id||degreeIds(),role:goalOld?.role||((state.degreeGoals||[]).some(g=>g.role==='primary')?'concurrent':'primary'),name:'UW Seattle Informatics — '+(f.stage==='core'?'supported core subset':f.stage==='transfer'?'transfer admission preparation':'current-student admission preparation'),institution,kind:f.stage==='core'?'Bachelor core subset':'Major admission preparation',source:f.stage==='core'?source.curriculum.source:source.source,catalogYear:'Confirm your catalog year',preset:'uw-info-'+f.stage,requirements:reqs,sharing:'review',advisorConfirmed:false,notes:[f.stage==='core'?'Already-admitted planning assumption; source conflict INFO 290 vs INFO 280 remains unresolved. This is not the complete degree.':'Published minimum prerequisite grade is 2.0; actual admission is selective.',f.stage==='transfer'?'INFO 200 is required after admission in the first or second enrolled quarter. A separate UW transfer application is required.':'Confirm prerequisite completion before the application quarter.', 'Alternative courses, enrollment access, offerings, AP/IB/Cr/S applicability and transcript-specific transfer credit need institutional review.']};const pool=new Map((state.degreeCourses||[]).map(c=>[MultiDegree.key(c),c]));for(const {course:c}of entries.values()){const old=pool.get(MultiDegree.key(c));if(old&&old.credits!==c.credits)return toast('A saved course has a different credit amount. Review it before loading this template.');pool.set(MultiDegree.key(c),{...old,...c})}state.degreeGoals||=[];if(goalOld)state.degreeGoals[state.degreeGoals.indexOf(goalOld)]=goal;else state.degreeGoals.push(goal);state.degreeCourses=[...pool.values()];state.profile={...state.profile,applicantTrack:f.stage==='transfer'?'transfer':f.stage==='current'?'current-seattle-undergrad':state.profile?.applicantTrack};save();render();toast('Source-backed Informatics checklist loaded; review scope and alternatives before registering.')}
function bindCurriculumTemplates(){document.querySelector('#info-template-form')?.addEventListener('submit',e=>{e.preventDefault();try{loadInfoTemplate(e.target)}catch(error){toast(error.message)}});document.querySelectorAll('[data-lock-alternative]').forEach(el=>el.onchange=()=>{const goal=state.degreeGoals.find(g=>g.id===el.dataset.goal),req=goal.requirements.find(r=>r.id===el.dataset.lockAlternative);if(el.value&&!req.choices.includes(el.value))return;req.lockedChoice=el.value;if(goal.preset)goal.edited=true;save();render()})}
function installCurriculumTemplates(){const old=degreePlanner;degreePlanner=()=>old().replace('<datalist id="degree-schools">',infoTemplateForm()+'<datalist id="degree-schools">');const beforeBind=bind;bind=()=>{beforeBind();bindCurriculumTemplates()}}
